// A sudoku board. The boxes are this puzzle's own business, so they're drawn here, and not worked
// out by the app. Change `box` for a different size of box.

const box = { rows: 2, cols: 2 };
const size = 88;

export function draw(world: World): string {
  const at = new Map(world.nodes.map((n) => [n.id, n.cells.at?.value as { row: number; col: number } | undefined]));
  const placed = world.choices.filter((c) => at.get(c.id));
  const rows = Math.max(...placed.map((c) => at.get(c.id)!.row)) + 1;
  const cols = Math.max(...placed.map((c) => at.get(c.id)!.col)) + 1;

  const cells = placed.map((c) => {
    const { row, col } = at.get(c.id)!;
    const [x, y] = [col * size, row * size];
    const left = c.options.filter((o) => o.possible);
    const pinned = c.options.find((o) => o.picked);
    const only = pinned ?? (left.length === 1 ? left[0] : undefined);
    if (only) {
      const colour = pinned ? "var(--accent)" : "var(--text)";
      return `<text data-pin-choice="${c.id}" data-pin-option="${only.id}" x="${x + size / 2}" y="${y + size / 2 + 12}" text-anchor="middle" font-size="36" fill="${colour}" style="cursor:pointer">${only.name}</text>`;
    }
    // Each option keeps its place, so what's been ruled out leaves a gap.
    const across = Math.ceil(Math.sqrt(c.options.length));
    return c.options
      .filter((o) => o.possible)
      .map((o) => {
        const i = c.options.indexOf(o);
        const [ox, oy] = [x + ((i % across) + 0.5) * (size / across), y + (Math.floor(i / across) + 0.5) * (size / across)];
        return `<text data-pin-choice="${c.id}" data-pin-option="${o.id}" x="${ox}" y="${oy + 5}" text-anchor="middle" font-size="15" fill="var(--muted)" style="cursor:pointer">${o.name}</text>`;
      })
      .join("");
  });

  const lines: string[] = [];
  for (let r = 0; r <= rows; r++) lines.push(line(0, r * size, cols * size, r * size, r % box.rows === 0));
  for (let c = 0; c <= cols; c++) lines.push(line(c * size, 0, c * size, rows * size, c % box.cols === 0));

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-2 -2 ${cols * size + 4} ${rows * size + 4}" width="${cols * size + 4}">${lines.join("")}${cells.join("")}</svg>`;
}

function line(x1: number, y1: number, x2: number, y2: number, heavy: boolean): string {
  return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${heavy ? "var(--text)" : "var(--border)"}" stroke-width="${heavy ? 3 : 1}" />`;
}
